// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.documentimport timber.log.Timberimport java.io.Fileimport java.security.KeyFactoryimport java.security.MessageDigestimport java.security.Signatureimport java.security.spec.X509EncodedKeySpecimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — SHA-256 + Ed25519 Pack Verifier (Module 6 v4 — Step 6.5). * * Verifies Regional Vision Packs (RVP) downloaded via [OkHttpPackDownloader] * using **two-layer verification**: * *  1. **SHA-256 integrity** — the file's actual SHA-256 must match *     [expectedSha256] (catches transmission corruption). *  2. **Ed25519 authenticity** — the [expectedSignature] must be a valid *     Ed25519 signature of the SHA-256 hash, signed by Roshan's pack-signing *     private key (the corresponding public key is baked into this class). *     This catches tampering — even if an attacker replaces both the file *     and the SHA-256 in the manifest, they cannot forge the signature *     without the private key. * * ## Why sign the SHA-256 hash (not the file) * *  - Ed25519 can sign arbitrary-length messages, but signing the 32-byte *    SHA-256 is faster (single-shot, no streaming) and lets us reuse the *    SHA-256 we already computed for integrity checking. *  - The SHA-256 hash is canonical — any byte-identical file produces the *    same hash, so signatures are stable across mirror re-hosts. * * ## Public key * * The default [publicKeyHex] is the production pack-signing public key * (Ed25519, 32 bytes). The corresponding private key is held offline by * Roshan's release pipeline; it is never shipped in the app. * * ## Testability * * For tests, inject a [FakePackVerifier] instead — this verifier performs * real Ed25519 crypto and requires a real signature to return true. */@Singletonclass Sha256PackVerifier @Inject constructor(    /**     * Ed25519 public key (raw 32 bytes, hex-encoded, 64 chars) used to     * verify pack signatures. Defaults to the production pack-signing key.     */    private val publicKeyHex: String = NOUS_PACK_SIGNING_PUBLIC_KEY_HEX,) : PackVerifier {    override fun verify(file: File, expectedSha256: String, expectedSignature: String): Boolean {        if (!file.exists()) {            Timber.tag(TAG).w("Pack file does not exist: ${file.absolutePath}")            return false        }        // 1. Compute SHA-256 of the file.        val hashBytes: ByteArray = try {            val digest = MessageDigest.getInstance("SHA-256")            file.inputStream().use { input ->                val buffer = ByteArray(BUFFER_SIZE)                var read = input.read(buffer)                while (read > 0) {                    digest.update(buffer, 0, read)                    read = input.read(buffer)                }            }            digest.digest()        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to compute SHA-256 for ${file.name}", t)            return false        }        val actualHashHex = hashBytes.joinToString("") { "%02x".format(it) }        if (!actualHashHex.equals(expectedSha256, ignoreCase = true)) {            Timber.tag(TAG).w("SHA-256 mismatch for ${file.name}: expected=$expectedSha256, actual=$actualHashHex")            return false        }        // 2. Ed25519 signature verification (signature signs the SHA-256 hash bytes).        if (expectedSignature.isBlank()) {            Timber.tag(TAG).w("No signature provided for ${file.name} — rejecting (signature required).")            return false        }        val signatureBytes = try {            expectedSignature.decodeHex()        } catch (t: Throwable) {            Timber.tag(TAG).w("Invalid signature hex for ${file.name}: ${t.message}")            return false        }        return try {            val publicKeyBytes = publicKeyHex.decodeHex()            val keySpec = X509EncodedKeySpec(encodeEd25519PublicKey(publicKeyBytes))            val publicKey = KeyFactory.getInstance("Ed25519").generatePublic(keySpec)            val verifier = Signature.getInstance("Ed25519")            verifier.initVerify(publicKey)            verifier.update(hashBytes)            val valid = verifier.verify(signatureBytes)            if (!valid) {                Timber.tag(TAG).w("Ed25519 signature invalid for ${file.name}.")            }            valid        } catch (t: Throwable) {            Timber.tag(TAG).e("Ed25519 signature verification failed for ${file.name}", t)            false        }    }    /**     * Wrap the raw 32-byte Ed25519 public key in an X.509 SubjectPublicKeyInfo     * structure so [KeyFactory] can decode it.     *     * The X.509 prefix for Ed25519 is fixed (per RFC 8410):     *   30 2a 30 05 06 03 2b 65 70 03 21 00 <32 raw bytes>     */    private fun encodeEd25519PublicKey(rawKeyBytes: ByteArray): ByteArray {        require(rawKeyBytes.size == ED25519_KEY_SIZE) {            "Ed25519 public key must be $ED25519_KEY_SIZE bytes, got ${rawKeyBytes.size}"        }        return X509_PREFIX + rawKeyBytes    }    /** Decode a hex string to bytes (lowercase/uppercase tolerant). */    private fun String.decodeHex(): ByteArray {        require(length % 2 == 0) { "Hex string must have even length, got $length" }        val out = ByteArray(length / 2)        for (i in indices step 2) {            out[i / 2] = ((Character.digit(this[i], 16) shl 4) +                Character.digit(this[i + 1], 16)).toByte()        }        return out    }    private companion object {        private const val TAG = "Sha256PackVerifier"        private const val BUFFER_SIZE = 8 * 1024        private const val ED25519_KEY_SIZE = 32        /**         * Production Ed25519 pack-signing public key (32 bytes, hex).         *         * Generated by Roshan's release pipeline. The corresponding private         * key is held offline and used only to sign Regional Vision Pack         * manifests before publishing.         */        private const val NOUS_PACK_SIGNING_PUBLIC_KEY_HEX =            "3aab4ad25623a1a2b99b4a7d9be604ac5f11d781dc10cd3746c02ceb16742396"        /** X.509 SubjectPublicKeyInfo prefix for Ed25519 (per RFC 8410). */        private val X509_PREFIX = byteArrayOf(            0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x03, 0x21, 0x00,        )    }}